INSERT INTO `hs_math_knowledge_points` VALUES (1,'rja.1.1.01','集合的含义与元素',16,31,NULL,'集合是具有确定属性的对象全体；元素属于集合记作 ∈。',10,1,'2026-10-24 10:55:39.844','2026-10-24 10:55:39.844'),(2,'rja.1.1.02','集合的表示法',16,31,NULL,'常用列举法与描述法表示集合。',20,1,'2026-10-24 10:55:39.844','2026-10-24 10:55:39.844'),(3,'rja.1.1.03','空集与全集（描述层面）',16,31,NULL,'空集不含任何元素，记作 ∅；讨论补集时常引入全集。',30,1,'2026-10-24 10:55:39.844','2026-10-24 10:55:39.844'),(4,'rja.1.2.01','子集与真子集',16,32,NULL,'A⊆B 表示 A 的元素都属于 B；真子集还要求 A≠B。',10,1,'2026-10-24 10:55:39.844','2026-10-24 10:55:39.844'),(5,'rja.1.2.02','集合相等',16,32,NULL,'A=B 当且仅当 A⊆B 且 B⊆A。',20,1,'2026-10-24 10:55:39.844','2026-10-24 10:55:39.844'),(6,'rja.1.3.01','并集',16,33,NULL,'A∪B 由属于 A 或属于 B 的元素组成。',10,1,'2026-10-24 10:55:39.844','2026-10-24 10:55:39.844'),(7,'rja.1.3.02','交集',16,33,NULL,'A∩B 由同时属于 A 与 B 的元素组成。',20,1,'2026-10-24 10:55:39.844','2026-10-24 10:55:39.844'),(8,'rja.1.3.03','补集',16,33,NULL,'在全集 U 下，∁_U A 由 U 中不属于 A 的元素组成。',30,1,'2026-10-24 10:55:39.844','2026-10-24 10:55:39.844'),(9,'rja.1.3.04','文氏图与综合运算',16,33,NULL,'用文氏图理解并、交、补的综合运算。',40,1,'2026-10-24 10:55:39.844','2026-10-24 10:55:39.844'),(10,'rja.1.4.01','充分条件',16,34,NULL,'若 p⇒q，则 p 是 q 的充分条件。',10,1,'2026-10-24 10:55:39.844','2026-10-24 10:55:39.844'),(11,'rja.1.4.02','必要条件',16,34,NULL,'若 p⇒q，则 q 是 p 的必要条件。',20,1,'2026-10-24 10:55:39.844','2026-10-24 10:55:39.844'),(12,'rja.1.4.03','充要条件',16,34,NULL,'若 p⇔q，则 p 是 q 的充要条件。',30,1,'2026-10-24 10:55:39.844','2026-10-24 10:55:39.844'),(13,'rja.1.5.01','全称量词',16,35,NULL,'∀ 表示“任意”；含全称量词的命题对论域中每一个对象成立。',10,1,'2026-10-24 10:55:39.844','2026-10-24 10:55:39.844'),(14,'rja.1.5.02','存在量词',16,35,NULL,'∃ 表示“存在”；含存在量词的命题至少对一个对象成立。',20,1,'2026-10-24 10:55:39.844','2026-10-24 10:55:39.844'),(15,'rja.1.5.03','含有量词的命题否定',16,35,NULL,'否定时全称与存在互换，并否定结论。',30,1,'2026-10-24 10:55:39.844','2026-10-24 10:55:39.844'),(16,'rja.3.1.01','函数的定义',18,41,NULL,'在数集 A 上，对任意 x∈A 按对应关系 f 有唯一确定的 y∈数集 B 与之对应，则称 f:A→B 为函数；记号 y=f(x)。',10,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738'),(17,'rja.3.1.02','定义域',18,41,NULL,'使函数有意义的自变量取值全体，记作 D(f) 或定义域；求定义域须考虑分式、根式、对数等限制。',20,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738'),(18,'rja.3.1.03','值域',18,41,NULL,'函数值组成的集合，记作 R(f) 或值域；可由解析式、图象或单调性等求取。',30,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738'),(19,'rja.3.1.04','对应关系',18,41,NULL,'函数三要素之一；同一对应关系可用不同字母表示，关键在“对应法则”本身而非符号。',40,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738'),(20,'rja.3.1.05','相同函数的判断',18,41,NULL,'两函数相同当且仅当定义域相同且对应关系相同（值域随之相同）；仅解析式写法不同可能仍为同一函数。',50,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738'),(21,'rja.3.1.06','解析法',18,41,NULL,'用数学表达式给出对应关系；是高中最常用的表示法，便于求值、讨论性质。',60,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738'),(22,'rja.3.1.07','图象法',18,41,NULL,'在平面直角坐标系中用点集表示函数；图象是点 (x,f(x)) 的轨迹，可直观读定义域、值域与单调性等。',70,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738'),(23,'rja.3.1.08','列表法',18,41,NULL,'用表格列出部分自变量与函数值；适合离散取值或实验数据，一般不能完整刻画连续函数全部性质。',80,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738'),(24,'rja.3.1.09','分段函数',18,41,NULL,'在定义域不同子集上用不同解析式给出对应关系；求值、图象与性质须按区间分别讨论再综合。',90,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738'),(25,'rja.3.1.10','函数求值',18,41,NULL,'给定自变量（或表达式）求函数值；含复合、分段、抽象函数 f(g(x)) 等常见求值题型。',100,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738'),(26,'rja.3.2.01','单调递增',18,42,NULL,'在区间 I 上，任意 x1<x2 都有 f(x1)<f(x2)（或 ≤）则称在 I 上（严格）单调递增；须明确所论区间。',10,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738'),(27,'rja.3.2.02','单调递减',18,42,NULL,'在区间 I 上，任意 x1<x2 都有 f(x1)>f(x2)（或 ≥）则称在 I 上（严格）单调递减；须明确所论区间。',20,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738'),(28,'rja.3.2.03','单调区间',18,42,NULL,'函数在其上保持单调的最大区间（或指定区间）；同一函数可有多个单调区间，书写时注意开闭。',30,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738'),(29,'rja.3.2.04','单调性判断',18,42,NULL,'用定义、图象、导数（后续）或已知结论判断单调性；比较 f(x1) 与 f(x2) 时注意变形等价性。',40,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738'),(30,'rja.3.2.05','单调性与不等式',18,42,NULL,'利用单调性比较大小或解不等式：同向可传递；复合时注意内外层单调性组合。',50,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738'),(31,'rja.3.2.06','最大值',18,42,NULL,'若存在 x0∈D 使对任意 x∈D 有 f(x)≤f(x0)，则 f(x0) 为最大值；注意定义域与是否取到。',60,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738'),(32,'rja.3.2.07','最小值与区间最值',18,42,NULL,'最小值类似定义；闭区间上连续函数必有最值。区间最值常结合端点与单调性（或极值）讨论。',70,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738'),(33,'rja.3.2.08','单调性与最值',18,42,NULL,'在单调区间上，端点（或区间趋向）决定最值；先定单调性再求最值，避免只看导数公式而忽略定义域。',80,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738'),(34,'rja.3.2.09','奇偶性定义与定义域对称',18,42,NULL,'讨论奇偶性必须先检验定义域关于原点对称；若不对称则既非奇也非偶。偶：f(-x)=f(x)；奇：f(-x)=-f(x)。零函数在对称定义域上既奇又偶。',90,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738'),(35,'rja.3.2.10','奇函数与偶函数的判断',18,42,NULL,'在定义域已关于原点对称的前提下，用定义、图象或赋值法判断奇/偶；不可仅凭解析式“看起来像”而跳过定义域。',100,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738'),(36,'rja.3.2.11','既奇又偶、非奇非偶及图象对称',18,42,NULL,'既奇又偶⇔在对称定义域上为常值 0（零函数）。非奇非偶常见。偶函数图象关于 y 轴对称；奇函数关于原点对称。',110,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738'),(37,'rja.3.2.12','奇偶性求值与综合应用',18,42,NULL,'用奇偶性求未知函数值、讨论分段/含参奇偶性。与单调性综合时必须明确所讨论的区间（如在 [0,+∞) 增则在对称负半轴相应递减等）。',120,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738'),(38,'rja.3.3.01','幂函数概念',18,43,NULL,'形如 y=x^α（α 为常数）的函数称为幂函数；定义域随 α 变化（整数、分数、无理数情形不同）。',10,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738'),(39,'rja.3.3.02','常见幂函数图象',18,43,NULL,'掌握 y=x,x^2,x^3,x^{1/2},x^{-1} 等典型图象过定点、象限分布与大致形状。',20,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738'),(40,'rja.3.3.03','幂函数性质概览',18,43,NULL,'综合定义域、值域、奇偶性、单调性与图象特征；不同 α 性质差异大，勿机械套用。',30,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738'),(41,'rja.3.3.04','幂函数单调性',18,43,NULL,'在各自定义域的合适区间上讨论增减；如 x^2 在 [0,+∞) 增、在 (-∞,0] 减；注意 α 与区间。',40,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738'),(42,'rja.3.3.05','幂函数奇偶性',18,43,NULL,'先看定义域是否关于原点对称，再判断奇偶：如 x^2 偶、x^3 奇、x^{1/2} 定义域非对称故非奇非偶。',50,1,'2026-10-24 19:56:46.738','2026-10-24 19:56:46.738');
